610: static COLD void close_internal(Dav1dContext **const c_out, int flush) {
611:     Dav1dContext *const c = *c_out;
612:     if (!c) return;
613: 
614:     if (flush) dav1d_flush(c);
615: 
616:     if (c->tc) {
617:         struct TaskThreadData *ttd = &c->task_thread;
618:         if (ttd->inited) {
619:             pthread_mutex_lock(&ttd->lock);
620:             for (unsigned n = 0; n < c->n_tc && c->tc[n].task_thread.td.inited; n++)
621:                 c->tc[n].task_thread.die = 1;
622:             pthread_cond_broadcast(&ttd->cond);
623:             pthread_mutex_unlock(&ttd->lock);
624:             for (unsigned n = 0; n < c->n_tc; n++) {
625:                 Dav1dTaskContext *const pf = &c->tc[n];
626:                 if (!pf->task_thread.td.inited) break;
627:                 pthread_join(pf->task_thread.td.thread, NULL);
628:                 pthread_cond_destroy(&pf->task_thread.td.cond);
629:                 pthread_mutex_destroy(&pf->task_thread.td.lock);
630:             }
631:             pthread_cond_destroy(&ttd->delayed_fg.cond);
632:             pthread_cond_destroy(&ttd->cond);
633:             pthread_mutex_destroy(&ttd->lock);
634:         }
635:         dav1d_free_aligned(c->tc);
636:     }
637: 
638:     for (unsigned n = 0; c->fc && n < c->n_fc; n++) {
639:         Dav1dFrameContext *const f = &c->fc[n];
640: 
641:         // clean-up threading stuff
642:         if (c->n_fc > 1) {
643:             dav1d_free(f->tile_thread.lowest_pixel_mem);
644:             dav1d_free(f->frame_thread.b);
645:             dav1d_free_aligned(f->frame_thread.cbi);
646:             dav1d_free_aligned(f->frame_thread.pal_idx);
647:             dav1d_free_aligned(f->frame_thread.cf);
648:             dav1d_free(f->frame_thread.tile_start_off);
649:             dav1d_free_aligned(f->frame_thread.pal);
650:         }
651:         if (c->n_tc > 1) {
652:             pthread_mutex_destroy(&f->task_thread.pending_tasks.lock);
653:             pthread_cond_destroy(&f->task_thread.cond);
654:             pthread_mutex_destroy(&f->task_thread.lock);
655:         }
656:         dav1d_free(f->frame_thread.frame_progress);
657:         dav1d_free(f->task_thread.tasks);
658:         dav1d_free(f->task_thread.tile_tasks[0]);
659:         dav1d_free_aligned(f->ts);
660:         dav1d_free_aligned(f->ipred_edge[0]);
661:         dav1d_free(f->a);
662:         dav1d_free(f->tile);
663:         dav1d_free(f->lf.mask);
664:         dav1d_free(f->lf.level);
665:         dav1d_free(f->lf.lr_mask);
666:         dav1d_free(f->lf.tx_lpf_right_edge[0]);
667:         dav1d_free(f->lf.start_of_tile_row);
668:         dav1d_free_aligned(f->rf.r);
669:         dav1d_free_aligned(f->lf.cdef_line_buf);
670:         dav1d_free_aligned(f->lf.lr_line_buf);
671:     }
672:     dav1d_free_aligned(c->fc);
673:     if (c->n_fc > 1 && c->frame_thread.out_delayed) {
674:         for (unsigned n = 0; n < c->n_fc; n++)
675:             if (c->frame_thread.out_delayed[n].p.frame_hdr)
676:                 dav1d_thread_picture_unref(&c->frame_thread.out_delayed[n]);
677:         dav1d_free(c->frame_thread.out_delayed);
678:     }
679:     for (int n = 0; n < c->n_tile_data; n++)
680:         dav1d_data_unref_internal(&c->tile[n].data);
681:     dav1d_free(c->tile);
682:     for (int n = 0; n < 8; n++) {
683:         dav1d_cdf_thread_unref(&c->cdf[n]);
684:         if (c->refs[n].p.p.frame_hdr)
685:             dav1d_thread_picture_unref(&c->refs[n].p);
686:         dav1d_ref_dec(&c->refs[n].refmvs);
687:         dav1d_ref_dec(&c->refs[n].segmap);
688:     }
689:     dav1d_ref_dec(&c->seq_hdr_ref);
690:     dav1d_ref_dec(&c->frame_hdr_ref);
691: 
692:     dav1d_ref_dec(&c->mastering_display_ref);
693:     dav1d_ref_dec(&c->content_light_ref);
694:     dav1d_ref_dec(&c->itut_t35_ref);
695: 
696:     dav1d_mem_pool_end(c->seq_hdr_pool);
697:     dav1d_mem_pool_end(c->frame_hdr_pool);
698:     dav1d_mem_pool_end(c->segmap_pool);
699:     dav1d_mem_pool_end(c->refmvs_pool);
700:     dav1d_mem_pool_end(c->cdf_pool);
701:     dav1d_mem_pool_end(c->picture_pool);
